const CAP = 80000;
const EXT_OK = { txt: true, md: true };
const j = $input.first().json;
const rawText = (j.text !== undefined && j.text !== null) ? String(j.text) : '';
const mode = (j.mode === 'fast') ? 'fast' : 'deep';
const fileName = j.fileName ? String(j.fileName) : '';
const jobId = j.jobId ? String(j.jobId) : 'job-' + Math.random().toString(36).slice(2, 8);
const startedAt = new Date().toISOString();
// DBG-03: strip bidi-override controls (U+202A-U+202E, U+2066-U+2069); count them for the sidecar
const bidiRemoved = (rawText.match(/[\u202A-\u202E\u2066-\u2069]/g) || []).length;
const cleaned = rawText.replace(/[\u202A-\u202E\u2066-\u2069]/g, '');
// DBG-09: one canonical trim at the source (single-chunk and multi-chunk paths alike)
const text = cleaned.trim();
// DBG-04: count Unicode code points, not UTF-16 code units
const charCount = Array.from(text).length;
let ext = '';
const m = fileName.match(/\.([A-Za-z0-9]+)$/);
// DBG-10: whitelist known text extensions; anything else falls back to the default branch
if (m) { const e = m[1].toLowerCase(); if (EXT_OK[e]) ext = e; }
function routeError(msg) {
  return [{ json: { route: 'error', jobId: jobId, fileName: fileName, mode: mode, ext: ext,
    text: '', originalText: '', charCount: charCount, bidiRemoved: bidiRemoved,
    errorMessage: msg, startedAt: startedAt } }];
}
if (text.length === 0) {
  return [{ json: { route: 'empty', jobId: jobId, fileName: fileName, mode: mode, ext: ext,
    text: '', originalText: '', charCount: 0, bidiRemoved: bidiRemoved,
    errorMessage: 'متن ورودی خالی است؛ چیزی برای ویرایش پیدا نشد.', startedAt: startedAt } }];
}
// DBG-11: punctuation-only input has nothing editable; reject before any LLM is burned
if (!/[\p{L}\p{N}\p{S}]/u.test(text)) {
  return routeError('متن ورودی فقط نشانه‌گذاری است و محتوای قابل ویرایش ندارد؛ لطفاً متن واقعی بدهید.');
}
if (charCount > CAP) {
  return routeError('متن ورودی (' + charCount + ' نویسه) از سقف مجاز (' + CAP + ' نویسه) بلندتر است؛ لطفاً آن را به بخش‌های کوچک‌تر تقسیم کنید.');
}
const badChars = (text.match(/[^\p{L}\p{N}\p{P}\p{S}\p{Z}\p{Cf}\n\r\t]/gu) || []).length;
const fffd = (text.match(/\uFFFD/g) || []).length;
if ((badChars + fffd) / Math.max(charCount, 1) > 0.05) {
  return routeError('فایل ورودی متن معتبر نیست؛ لطفاً یک فایل متنی txt یا md بدهید.');
}
return [{ json: { route: 'ok', jobId: jobId, fileName: fileName, mode: mode, ext: ext,
  text: text, originalText: text, charCount: charCount, bidiRemoved: bidiRemoved,
  errorMessage: '', startedAt: startedAt } }];

const j = $input.first().json;
const text = j.text;
const LIMIT = 12000, TARGET = 8000, MAXC = 10;
const cpLen = (s) => Array.from(s).length;
function splitParas(t) {
  const parts = t.split(/\n\s*\n/).map(s => s.trim()).filter(s => s.length > 0);
  return parts.length > 0 ? parts : [t];
}
// DBG-02: slice on code points so a UTF-16 surrogate pair is never cut in half
function sliceCp(s, start, end) { return Array.from(s).slice(start, end).join(''); }
function splitLongPara(p) {
  const out = [];
  const total = cpLen(p);
  for (let i = 0; i < total; i += TARGET) out.push(sliceCp(p, i, i + TARGET));
  return out;
}
// DBG-05: redistribute evenly when over MAXC instead of ballooning the last chunk
function rebalanceEven(chunks) {
  if (chunks.length <= MAXC) return chunks;
  const cps = Array.from(chunks.join('\n\n'));
  const per = Math.ceil(cps.length / MAXC);
  const out = [];
  for (let i = 0; i < cps.length; i += per) out.push(cps.slice(i, i + per).join('').trim());
  return out.filter(s => s.length > 0);
}
// DBG-02: post-split guard, defense in depth; throws a coded error, never silent
function assertNoLoneSurrogates(chunks) {
  for (const c of chunks) {
    for (let i = 0; i < c.length; i++) {
      const u = c.charCodeAt(i);
      if (u >= 0xD800 && u <= 0xDBFF) {
        const v = c.charCodeAt(i + 1);
        if (!(v >= 0xDC00 && v <= 0xDFFF)) throw new Error('ERR_SPLIT_SURROGATE');
        i++; // skip the low surrogate of this valid pair
      } else if (u >= 0xDC00 && u <= 0xDFFF) {
        throw new Error('ERR_SPLIT_SURROGATE');
      }
    }
  }
}
let chunks;
if (cpLen(text) <= LIMIT) {
  chunks = [text];
} else {
  chunks = [];
  let cur = '', curLen = 0;
  for (const p of splitParas(text)) {
    const pl = cpLen(p);
    if (pl > TARGET) {
      if (cur) { chunks.push(cur); cur = ''; curLen = 0; }
      for (const piece of splitLongPara(p)) chunks.push(piece);
    } else if (cur && curLen + 2 + pl > TARGET) {
      chunks.push(cur); cur = p; curLen = pl;
    } else if (cur) {
      cur = cur + '\n\n' + p; curLen = curLen + 2 + pl;
    } else {
      cur = p; curLen = pl;
    }
  }
  if (cur) chunks.push(cur);
  chunks = rebalanceEven(chunks);
}
assertNoLoneSurrogates(chunks);
// BUG-R5-1: the BUG-R2-6 pool reset is removed. Live in n8n 2.42.3, the
// workflow-variables object is undefined in Code nodes, so the reset threw
// "Cannot set properties of undefined" on every pipeline run.
// The final barrier («انباشت: خوانش آخر») is now stateless, so no reset is needed.
return chunks.map((c, i) => ({ json: {
  jobId: j.jobId, fileName: j.fileName, mode: j.mode, ext: j.ext,
  bidiRemoved: j.bidiRemoved || 0,
  chunkIndex: i, chunkCount: chunks.length,
  text: c, originalText: c, inputLen: c.length, startedAt: j.startedAt } }));

const items = $input.all().map(i => i.json);
// DBG-08: never TypeError on empty input; route a clean Persian error instead
if (items.length === 0) {
  return [{ json: { route: 'error', jobId: '', fileName: '', mode: 'deep',
    errorMessage: 'هیچ تکه‌ای برای ادغام نرسید؛ اجرا متوقف شد.',
    startedAt: new Date().toISOString() } }];
}
const bad = items.find(it => it.route === 'error' || it.route === 'empty');
if (bad) {
  return [{ json: { route: bad.route, jobId: bad.jobId, fileName: bad.fileName, mode: bad.mode,
    errorMessage: bad.errorMessage || 'خطای نامشخص در پردازش تکه‌ها', startedAt: bad.startedAt } }];
}
items.sort((a, b) => a.chunkIndex - b.chunkIndex);
const first = items[0];
// DBG-01 complement: a lost or duplicated chunk must fail loudly, never silently
const want = first.chunkCount;
if (items.length !== want) {
  return [{ json: { route: 'error', jobId: first.jobId, fileName: first.fileName, mode: first.mode,
    errorMessage: 'تعداد تکه‌های برگشتی (' + items.length + ') با تعداد مورد انتظار (' + want + ') نمی‌خواند؛ اجرا متوقف شد.',
    startedAt: first.startedAt } }];
}
const seen = {};
for (const it of items) seen[it.chunkIndex] = true;
for (let k = 0; k < want; k++) {
  if (!seen[k]) {
    return [{ json: { route: 'error', jobId: first.jobId, fileName: first.fileName, mode: first.mode,
      errorMessage: 'تکه شماره ' + (k + 1) + ' در میانه راه گم شد؛ اجرا متوقف شد.',
      startedAt: first.startedAt } }];
  }
}
const text = items.map(it => it.text).join('\n\n');
const originalText = items.map(it => it.originalText).join('\n\n');
return [{ json: { route: 'ok', jobId: first.jobId, fileName: first.fileName, mode: first.mode,
  ext: first.ext, text: text, originalText: originalText, charCount: text.length,
  bidiRemoved: first.bidiRemoved || 0,
  chunkCount: items.length, stage: 'merged', startedAt: first.startedAt } }];

