// thus items stay in input order and are never dropped; positional pairing
// by index is valid only under preconditions P1-P6 (see architecture-v1.md appendix).
// P6 upstream contract: «حالت: سریع؟».all(0) (fast branch) + «اعمال: قوانین».all() (deep branch) -- exactly one non-empty per run; union == the stream that entered «ویراستار: پاس ۱».
const agentItems = $input.all();
function safeAll(nm, br) { try { const r = $(nm); return br === undefined ? r.all() : r.all(br); } catch (e) { return []; } }
