// بقیهٔ ویرایش‌ها دست نمی‌خورد.
var items = [];
try { items = $input.all(); } catch (e) { items = []; }

function tokens(s) { return String(s == null ? '' : s).split(/\s+/).filter(function (x) { return x !== ''; }); }
function escRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function normW(w) { return String(w).replace(/‌/g, '').replace(/[ً-ٰٖ]/g, '').replace(/[.،؟؛:!؟»«"'()\[\]{}…-]/g, ''); }
var FA = '[\\u0600-\\u06FF]';

// --- نگاشت‌های مکانیکی (تکرارِ «پیش‌نگهبان مکانیکی»؛ جبری و قطعی) ---
var ETERNAL_RE = [
  [/شایان ذکر است که/g, ''], [/شایان ذکر است/g, ''],
  [/لازم به ذکر است که/g, ''], [/لازم به ذکر است/g, ''],
  [/در دنیای امروز[،\s]*/g, 'امروزه '],
  [/اتخاذ گردید/g, 'گرفته شد'], [/اتخاذ می‌گردد/g, 'گرفته می‌شود'],
  [/می‌باشد که/g, ''], [/می‌باشند که/g, ''],
  [/می‌باشند/g, 'هستند'], [/می‌باشد/g, 'است'],
  [/(^|\s)گردیدند(?=\s|[.،؟؛:!؟»])/g, '$1شدند'],
  [/(^|\s)گردید(?=\s|[.،؟؛:!؟»])/g, '$1شد'],
  [/(^|\s)کلیه(?=\s)/g, '$1همه'], [/(^|\s)جهت(?=\s)/g, '$1برای'],
  [/رفاه حال/g, 'راحتی']
];
function mechPreClean(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < ETERNAL_RE.length; k++) t = t.replace(ETERNAL_RE[k][0], ETERNAL_RE[k][1]);
  return t.replace(/ {2,}/g, ' ').replace(/\s([.،؟؛:!؟»])/g, '$1').trim();
}

function fixMerge(orig, edited) {
  var ot = tokens(orig), oSet = {};
  ot.forEach(function (t) { oSet[t] = 1; });
  var txt = edited, applied = [];
  for (var i = 0; i < ot.length - 1; i++) {
    var merged = ot[i] + ot[i + 1];
    if (oSet[merged]) continue;
    var re = new RegExp('(^|\\s)' + escRe(merged) + '(?=\\s|$)', 'g');
    var nt = txt.replace(re, '$1' + ot[i] + ' ' + ot[i + 1]);
    if (nt !== txt) { applied.push('merge:' + merged); txt = nt; }
  }
  return { text: txt, applied: applied };
}

function fixYaBeforeRa(orig, edited) {
  function beforeRa(s) {
    var map = {}, m;
    var re = new RegExp('(' + FA + '+) را(?=\\s|[.،؟؛:!؟»\\]])', 'g');
    while ((m = re.exec(s))) map[m[1]] = 1;
    return map;
  }
  var oB = beforeRa(orig), eB = beforeRa(edited), oWords = {};
  tokens(orig).forEach(function (t) { oWords[t] = 1; });
  var txt = edited, applied = [];
  for (var w in eB) {
    var last = w.slice(-1);
    if ((last === 'ی' || last === 'ي') && w.length > 1) {
      var base = w.slice(0, -1);
      if (oB[base] && !oWords[w]) {
        var re = new RegExp('(^|\\s)' + escRe(w) + ' را(?=\\s|[.،؟؛:!؟»\\]])', 'g');
        var nt = txt.replace(re, '$1' + base + ' را');
        if (nt !== txt) { applied.push('ya:' + w); txt = nt; }
      }
    }
  }
  return { text: txt, applied: applied };
}

function fixSingleDeletion(orig, edited) {
  var ot = tokens(orig), et = tokens(edited);
  if (ot.length - et.length !== 1) return { text: edited, applied: [] };
  var i = 0;
  while (i < et.length && ot[i] === et[i]) i++;
  var restO = ot.slice(i + 1), restE = et.slice(i);
  if (restO.length !== restE.length) return { text: edited, applied: [] };
  for (var k = 0; k < restO.length; k++) if (restO[k] !== restE[k]) return { text: edited, applied: [] };
  var w = ot[i];
  if (w.replace(/‌/g, '').length < 4) return { text: edited, applied: [] };
  return { text: et.slice(0, i).concat([w], et.slice(i)).join(' '), applied: ['undel:' + w] };
}

// ===== بخش تازهٔ «متخصص ۱: نگهبان نقش‌نما» (۱۴۰۵/۰۷/۱۸) =====
// باگ T01: مدل گاهی حرف اضافه را می‌اندازد («به سر کار می‌روم» ← «سر کار می‌روم»).
// قانون: فهرست بستهٔ حروف اضافهٔ محافظت‌شده؛ اگر تنها تفاوت اصل و متن نهایی
// افتادنِ یکی از همین‌ها باشد (واژهٔ بعدش سر جایش و عوض‌نشده)، برمی‌گردد.
// «ولی» حرف ربط است و «ما» ضمیر — در فهرست نیستند، پس در T19 برنمی‌گردند.
var PROTECTED_PREPS = { 'به': 1, 'از': 1, 'در': 1, 'با': 1, 'برای': 1, 'را': 1 };
function normTok(w) { return String(w).replace(/‌/g, ''); } // نقطه‌گذاری می‌ماند تا تراز دقیق باشد
function fixDroppedPrep(orig, edited) {
  var ot = tokens(orig), et = tokens(edited);
  if (ot.length - et.length !== 1) return { text: edited, applied: [] };
  var i = 0;
  while (i < et.length && normTok(ot[i]) === normTok(et[i])) i++;
  if (i >= ot.length) return { text: edited, applied: [] };
  var restO = ot.slice(i + 1), restE = et.slice(i);
  if (restO.length !== restE.length) return { text: edited, applied: [] };
  for (var k = 0; k < restO.length; k++) if (normTok(restO[k]) !== normTok(restE[k])) return { text: edited, applied: [] };
  var w = ot[i];
  if (!PROTECTED_PREPS[w]) return { text: edited, applied: [] };
  return { text: et.slice(0, i).concat([w], et.slice(i)).join(' '), applied: ['prep:' + w] };
}

// باگ T19: مدل ضمیر فاعلیِ زائد را نگه می‌دارد («…، ما به پارک رفتیم» ← باید «…، به پارک رفتیم»).
// قانون (محافظه‌کار؛ فقط حالت روشن): ضمیر فاعلیِ من/تو/ما/شما/آنها حذف می‌شود اگر
// همهٔ این‌ها برقرار باشد:
//  ۱) ضمیر اول جمله نباشد (ضمیر آغازین معمولاً موضع/تأکید دارد: «من نمی‌دانم…»)؛
//  ۲) فعلِ پایان جمله شناسهٔ شخصیِ همان ضمیر را داشته باشد (رفتیم ← ما)؛
//  ۳) هیچ نشانهٔ تأکید/تضادی در جمله نباشد (هم، نیز، فقط، نه، بلکه، خود)؛
//  ۴) ضمیر مفعول نباشد (بعدش «را» نیامده باشد).
// «او» کنار گذاشته شد چون شناسهٔ سوم‌شخص مفرد نشانهٔ متمایز ندارد و تشخیصش حدسی می‌شود.
var PRON_SUFFIX = { 'من': 'م', 'تو': 'ی', 'ما': 'یم', 'شما': 'ید', 'آنها': 'ند' };
var EMPH_TOKENS = { 'هم': 1, 'نیز': 1, 'فقط': 1, 'نه': 1, 'بلکه': 1, 'خود': 1 };
function verbLike(v, suf) {
  if (v.length < suf.length + 2) return false;
  if (v.slice(-suf.length) !== suf) return false;
  if (suf.length >= 2) return true; // یم/ید/ند به‌اندازهٔ کافی متمایزند
  if (/^(ن?می)/.test(v)) return true; // مضارع: می‌روم، نمی‌دانم
  return /[تد]$/.test(v.slice(0, -1)); // ماضی: رفتم، کردم، شدم، بودم…
}
function fixRedundantPronoun(orig, edited) {
  var et = tokens(edited);
  var out = [], applied = [], start = 0;
  for (var s = 0; s <= et.length; s++) {
    var isEnd = (s === et.length) || /[.؟!؛]$/.test(et[s]);
    if (!isEnd) continue;
    var end = (s === et.length) ? et.length - 1 : s;
    if (end >= start) {
      var verbTok = normW(et[end]); // فعلِ پایان جمله، بدون نقطه‌گذاری و نیم‌فاصله
      for (var i = start; i <= end; i++) {
        var p = et[i], drop = true;
        if (i === start) drop = false;
        else if (!PRON_SUFFIX[p]) drop = false;
        else if (!verbLike(verbTok, PRON_SUFFIX[p])) drop = false;
        else if (et[i + 1] === 'را') drop = false;
        else {
          for (var j = start; j <= end; j++) {
            if (j !== i && EMPH_TOKENS[et[j]]) { drop = false; break; }
          }
        }
        if (drop) applied.push('pron:' + p); else out.push(et[i]);
      }
    }
    start = s + 1;
  }
  return { text: out.join(' '), applied: applied };
}

return items.map(function (it) {
  var j = Object.assign({}, it.json);
  var orig = j.originalText, txt = j.text;
  if (typeof orig !== 'string' || typeof txt !== 'string' || orig.length === 0 || txt.length === 0 || orig === txt) {
    return { json: j };
  }

  // قانون واژهٔ تازه: اگر اصل با نگاشت‌های مکانیکی تمیز می‌شده، متن تمیزشده را
  // بازسازی کن؛ اگر متن نهایی واژهٔ واقعاً تازه‌ای دارد (پس از نرمال‌سازی نه در
  // اصل بوده نه در متن تمیزشده)، یعنی مدل مترادف‌بازی کرده — برگردان به تمیزشده.
  var preT = mechPreClean(orig);
  if (preT !== orig && txt !== preT) {
    var known = {};
    tokens(orig).forEach(function (t) { var n = normW(t); if (n.length >= 3) known[n] = 1; });
    tokens(preT).forEach(function (t) { var n = normW(t); if (n.length >= 3) known[n] = 1; });
    var fresh = [], seen = {};
    tokens(txt).forEach(function (t) {
      var n = normW(t);
      if (n.length >= 3 && !known[n] && !seen[n]) { seen[n] = 1; fresh.push(n); }
    });
    if (fresh.length > 0) {
      j.text = preT;
      j.guard_warnings = (j.guard_warnings || []).concat(['newword:' + fresh.join(',')]);
      return { json: j };
    }
  }

  // اصلاح‌های جراحی
  var warns = [], t = txt, r;
  r = fixMerge(orig, t); t = r.text; warns = warns.concat(r.applied);
  r = fixYaBeforeRa(orig, t); t = r.text; warns = warns.concat(r.applied);
  r = fixDroppedPrep(orig, t); t = r.text; warns = warns.concat(r.applied); // تازه: حرف‌اضافهٔ افتاده (T01)
  r = fixSingleDeletion(orig, t); t = r.text; warns = warns.concat(r.applied);
  r = fixRedundantPronoun(orig, t); t = r.text; warns = warns.concat(r.applied); // تازه: ضمیر فاعلیِ زائد (T19)
  if (warns.length > 0) {
    j.text = t;
    j.guard_warnings = (j.guard_warnings || []).concat(warns);
  }
  return { json: j };
});

// نگهبان نقطه‌گذاری (۱۴۰۵/۰۷/۱۸، متخصص ۲): مقایسهٔ originalText و text در هر تکه.
// دو قانون قطعیِ نقطه‌گذاری؛ منطق regex/توکن، بدون LLM. بقیهٔ ویرایش‌ها دست نمی‌خورد.
var items = [];
try { items = $input.all(); } catch (e) { items = []; }

function tokens(s) { return String(s == null ? '' : s).split(/\s+/).filter(function (x) { return x !== ''; }); }
function normTok(t) {
  return String(t).replace(/‌/g, '').replace(/[ً-ٰٖ]/g, '')
    .replace(/[,;.،؟؛:!؟»«"'()\[\]{}…\-–—/\\|]/g, '')
    .replace(/ي/g, 'ی').replace(/ك/g, 'ک');
}
function splitTok(tok) {
  var t = String(tok), i = t.length;
  var P = '.,;،؛:؟!…»«"\'()[]{}';
  while (i > 0 && P.indexOf(t.charAt(i - 1)) !== -1) i--;
  return { word: t.slice(0, i), trail: t.slice(i) };
}
// کلید تراز از روی بخش واژه (بدون دنبالهٔ نقطه‌گذاری) تا «بود;» و «بود؛» یکی شوند
function keyOf(word, raw) { var n = normTok(word); return n !== '' ? n : '§' + raw; }
function sentCount(s) {
  var t = String(s).replace(/\s+$/, '');
  var m = t.match(/[.؟!]/g), c = m ? m.length : 0;
  if (/[.؟!]$/.test(t)) c--;
  return c < 0 ? 0 : c;
}

// فعل‌های امر دوم‌شخص (ساده و مؤدبانه)؛ فعل‌های مرکب با فعل سبک انتهایی پوشش داده می‌شوند
var IMP_LIST = ('کن بکن نکن مکن باش نباش مباش شو بشو نشو مشو بمان نمان ممان ' +
  'بایست نایست بگذر نگذر مگذر برو نرو مرو بیا نیا میا ببین نبین مبین ' +
  'بشنو نشنو مشنو بگو نگو مگو بخوان نخوان مخوان بنویس ننویس منویس ' +
  'بده نده مده بگیر نگیر مگیر ببر نبر مبر بیاور نیاور میاور بخر نخر مخر ' +
  'بفروش نفروش بکش نکش مکش بزن نزن مزن بپوش نپوش بخور نخور مخور ' +
  'بنوش ننوش منوش بخواب نخواب مخواب بنشین نشین منشین برخیز نخیز ' +
  'بدان ندان بفهم نفهم بپرس نپرس مپرس بگرد نگرد مگرد بچرخ نچرخ ' +
  'برگرد برنگرد بشتاب نشتاب بکوش نکوش بجنب نجنب بگذران نگذران ' +
  'بساز نساز مساز بشکن نشکن ببند نبند مبند بگشا نگشا بردار ندار ' +
  'بگذار نگذار مگذار بسپار نسپار ببخش نبخش بدار بدو بپر ' +
  'بفرما بفرمایید بفرمائید بخوانید بگویید ببینید بشنوید بروید بیایید ' +
  'بدهید بگیرید بکنید نکنید باشید نباشید کنید شوید بشوید بنشینید ' +
  'بدانید بفهمید بپرسید').split(' ');
var IMP = {};
IMP_LIST.forEach(function (w) { IMP[normTok(w)] = 1; });

// تراز واژه‌به‌واژه با LCS روی کلید نرمال‌شده؛ فقط وقتی تمیز (۱به۱) برگردان
function alignWords(oW, eW) {
  var n = oW.length, m = eW.length, i, j;
  var dp = [];
  for (i = 0; i <= n; i++) { dp.push([]); for (j = 0; j <= m; j++) dp[i].push(0); }
  for (i = n - 1; i >= 0; i--) for (j = m - 1; j >= 0; j--)
    dp[i][j] = (oW[i].key === eW[j].key) ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  var pairs = [], clean = true;
  i = 0; j = 0;
  while (i < n && j < m) {
    if (oW[i].key === eW[j].key) { pairs.push([i, j]); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) { i++; clean = false; }
    else { j++; clean = false; }
  }
  if (i !== n || j !== m) clean = false;
  return { pairs: pairs, clean: clean };
}

function guardPunct(orig, edited) {
  var ow = tokens(orig).map(function (t) { var p = splitTok(t); return { raw: t, word: p.word, trail: p.trail, key: keyOf(p.word, t) }; });
  var ew = tokens(edited).map(function (t) { var p = splitTok(t); return { raw: t, word: p.word, trail: p.trail, key: keyOf(p.word, t) }; });
  var al = alignWords(ow, ew);
  if (!al.clean || ow.length === 0) return { text: edited, applied: [] };
  var map = {};
  al.pairs.forEach(function (pr) { map[pr[1]] = pr[0]; });
  var n = ew.length;
  var out = ew.map(function (e) { return e.raw; });
  var applied = [];

  for (var j = 0; j < n; j++) {
    var e = ew[j], o = ow[map[j]], isLast = (j === n - 1);
    if (isLast) continue;

    // قانون ۱ (رفت): مدل نقطه‌ای اضافه کرده که در اصل «,» یا «;» بوده ← برگردان
    if (e.trail.indexOf('.') !== -1 && /[,;،؛]/.test(o.trail)) {
      var to = /[;؛]/.test(o.trail) ? '؛' : '،';
      out[j] = e.word + (e.trail === '.' ? to : e.trail.replace('.', to));
      applied.push('sentfix:.→' + to);
      continue;
    }
    // قانون ۱ (برگشت): مدل نقطهٔ میانی اصل را به «،/؛» تبدیل کرده ← نقطه برگردد
    if (o.trail.indexOf('.') !== -1 && e.trail.indexOf('.') === -1 && /[,;،؛]/.test(e.trail)) {
      var fromCh = e.trail.indexOf(',') !== -1 ? ',' : (e.trail.indexOf('،') !== -1 ? '،' : (e.trail.indexOf(';') !== -1 ? ';' : '؛'));
      out[j] = e.word + e.trail.replace(fromCh, '.');
      applied.push('sentfix:' + fromCh + '→.');
      continue;
    }
    // قانون ۲: «؛» مدل که در اصل دقیقاً «,» بوده و دو طرفش فعل امر/جمله‌وارهٔ کوتاه‌اند ← «،»
    if (/[؛;]/.test(e.trail) && o.trail.indexOf(',') !== -1) {
      var lv = normTok(e.word);
      if (IMP[lv]) {
        var k = j + 1, rw = [];
        while (k < n) { rw.push(ew[k]); if (/[.؟!]/.test(ew[k].trail)) break; k++; }
        var rlast = rw.length ? normTok(rw[rw.length - 1].word) : '';
        if (rw.length > 0 && (IMP[rlast] || rw.length <= 3)) {
          out[j] = e.word + e.trail.replace(/[؛;]/g, '،');
          applied.push('impfix:؛→،');
        }
      }
    }
  }

  var text = applied.length ? out.join(' ') : edited;
  // شمارش جمله‌های میانی (بدون نقطهٔ پایانی)؛ اختلافِ باقی‌مانده فقط هشدار
  var oc = sentCount(orig), ec = sentCount(text);
  if (oc !== ec) applied.push('sentcount:' + oc + '→' + ec);
  return { text: text, applied: applied };
}

return items.map(function (it) {
  var j = Object.assign({}, it.json);
  var orig = j.originalText, txt = j.text;
  if (typeof orig !== 'string' || typeof txt !== 'string' || orig.length === 0 || txt.length === 0 || orig === txt) {
    return { json: j };
  }
  var r = guardPunct(orig, txt);
  if (r.applied.length > 0) {
    j.text = r.text;
    j.guard_warnings = (j.guard_warnings || []).concat(r.applied);
  }
  return { json: j };
});
